{
  "commonPhenomenon": "支付网关显示交易成功，但本地系统未记录到回调通知，导致资金状态与通道结果不一致。",
  "facts": [
    {
      "statement": "支付网关已完成交易，本地系统未记录回调到达。",
      "evidenceIds": [
        "E-012"
      ]
    }
  ],
  "differences": [
    {
      "description": "通道侧确认为支付成功，而平台侧因未收到回调，资金状态可能仍为处理中或未完成，形成终态冲突。",
      "evidenceIds": [
        "E-012"
      ]
    }
  ],
  "possibleExplanations": [
    {
      "hypothesis": "网络传输故障导致通道回调未能送达平台入口。",
      "evidenceIds": [
        "E-012"
      ],
      "verification": "检查平台入口访问日志和防火墙记录，确认在支付时间附近是否有来自通道的HTTP请求被丢弃或超时。"
    },
    {
      "hypothesis": "回调验签失败导致平台主动拒绝接收通知。",
      "evidenceIds": [
        "E-012"
      ],
      "verification": "比对通道发送的签名与平台配置的密钥，检查应用日志中是否存在验签失败的错误记录。"
    },
    {
      "hypothesis": "回调投递延迟，尚未到达平台系统。",
      "evidenceIds": [
        "E-012"
      ],
      "verification": "通过可信只读查单接口再次查询通道交易状态，并等待一段时间观察是否收到迟到的回调通知。"
    }
  ],
  "checkSteps": [
    "使用商户订单号和通道交易号确认是同一笔交易。",
    "比对通道支付时间、回调投递记录（如有）、平台入口访问日志和商户通知应答。",
    "检查日志的时间范围、时区设置与保留期限，确保未遗漏早期或晚期日志。",
    "若缺少任一侧记录，先补齐对应证据再区分未投递、网络失败、验签失败或处理失败。",
    "由人工复核资金流水，确认是否存在重复扣款或资金差异。"
  ],
  "missingInformation": [
    "平台入口的具体访问日志（含时间戳和IP）。",
    "通道侧的回调投递历史记录及状态。",
    "当前平台资金状态的详细快照（如processing还是其他状态）。",
    "商户通知应答的处理结果日志。"
  ],
  "knowledgeCitations": [
    "lost-callback",
    "terminal-conflict"
  ],
  "knowledgeOmissionReason": null
}
